import { create } from 'zustand';

type Trigger = 'copy' | 'export' | null;

interface DedicationState {
  isOpen: boolean;
  trigger: Trigger;
  open: (trigger: Trigger) => void;
  close: () => void;
}

export const useDedicationStore = create<DedicationState>((set) => ({
  isOpen: false,
  trigger: null,
  open: (trigger) => set({ isOpen: true, trigger }),
  close: () => set({ isOpen: false, trigger: null }),
}));