// Lazy-load data modules (JSON imports are bundled by Vite at build time).
// We keep them as async functions so the shell can load fast.

import type { TermMetadataFile } from '@/types/knowledge.types';
import type { InteractionProtocolsFile } from '@/types/protocol.types';
import type { StrategyFile } from '@/lib/engine/StrategyPlanner';
import type { CompatibilityFile } from '@/lib/engine/CompatibilityChecker';
import type { RawKnowledgeBase, RawTerm } from '@/types/knowledge.types';
import examplesEnData from '@/data/term-examples-en.json';

let rawKBCache: RawKnowledgeBase | null = null;
let rawTermMapCache: Map<number, RawTerm> | null = null;
let metadataCache: TermMetadataFile | null = null;
let protocolsCache: InteractionProtocolsFile | null = null;
let strategiesCache: StrategyFile | null = null;
let compatibilityCache: CompatibilityFile | null = null;

export async function loadTermMetadata(): Promise<TermMetadataFile> {
  if (metadataCache) return metadataCache;
  const mod = await import('@/data/term-metadata.json');
  metadataCache = mod.default as unknown as TermMetadataFile;
  return metadataCache;
}

export async function loadProtocols(): Promise<InteractionProtocolsFile> {
  if (protocolsCache) return protocolsCache;
  const mod = await import('@/data/interaction-protocols.json');
  protocolsCache = mod.default as unknown as InteractionProtocolsFile;
  return protocolsCache;
}

export async function loadStrategies(): Promise<StrategyFile> {
  if (strategiesCache) return strategiesCache;
  const mod = await import('@/data/strategies.json');
  strategiesCache = mod.default as unknown as StrategyFile;
  return strategiesCache;
}

export async function loadCompatibility(): Promise<CompatibilityFile> {
  if (compatibilityCache) return compatibilityCache;
  const mod = await import('@/data/term-compatibility.json');
  compatibilityCache = mod.default as unknown as CompatibilityFile;
  return compatibilityCache;
}



export async function loadRawKnowledgeBase(): Promise<RawKnowledgeBase> {
  if (rawKBCache) return rawKBCache;
  const res = await fetch(`${import.meta.env.BASE_URL}data/knowledge-base.json`);
  if (!res.ok) throw new Error('Failed to load knowledge base');
  rawKBCache = (await res.json()) as RawKnowledgeBase;
  return rawKBCache;
}

export async function getRawTermMap(): Promise<Map<number, RawTerm>> {
  if (rawTermMapCache) return rawTermMapCache;

  const kb = await loadRawKnowledgeBase();
  const map = new Map<number, RawTerm>();

  // 🔑 الترقيم العالمي: نتجاهل أي `id` داخلي ونستخدم runningId
  // هذا يضمن أن الخريطة تُطابق term-metadata.json (1-65)
  let runningId = 1;
  for (const section of kb.sections) {
    for (const item of section.items) {
      map.set(runningId, item);
      runningId++;
    }
  }

  // 🔑 Fallback: إذا لم تُغطِّ الأقسام كل الـ65 مصطلحاً،
  // نستخدم editing_tips لملء المعرفات المتبقية
  if (kb.editing_tips && kb.editing_tips.length > 0) {
    for (let i = 0; i < kb.editing_tips.length && runningId <= 65; i++) {
      if (map.has(runningId)) {
        runningId++;
        continue;
      }
      const tip = kb.editing_tips[i];
      // التنسيق: "نص عربي (English Name)"
      const match = tip.match(/\(([^)]+)\)/);
      const termEn = match ? match[1].trim() : `Editing Tip ${i + 1}`;
      const termAr = match ? tip.replace(/\([^)]+\)/, '').trim() : tip;

      map.set(runningId, {
        id: runningId,
        term_en: termEn,
        term_ar: termAr,
        detailed_explanation: tip,
        practical_application: '',
        examples: [],
        pro_tips: [],
      });
      runningId++;
    }
  }

  rawTermMapCache = map;
  return map;
}
// ============================================================
// English term examples — STATIC import (guaranteed sync)
// The file is ~10KB, safe to bundle with the main app.
// This eliminates any "not loaded yet" race condition.
// ============================================================


interface TermExamplesEnFile {
  version: string;
  description: string;
  examples: Record<string, string>;
}

const _examplesEn = examplesEnData as unknown as TermExamplesEnFile;

export function getEnglishExampleSync(termId: number): string | undefined {
  return _examplesEn.examples[String(termId)];
}

// Backwards-compatible no-op (still used by main.tsx)
export async function loadEnglishExamples(): Promise<Record<string, string>> {
  return _examplesEn.examples;
}