import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import type { UserProfile } from '@/types/profile.types';

interface ProfileState {
  profile: UserProfile;
  setProfile: (p: Partial<UserProfile>) => void;
  enable: () => void;
  disable: () => void;
  reset: () => void;
}

const DEFAULT: UserProfile = { enabled: false };

export const useProfileStore = create<ProfileState>()(
  persist(
    (set) => ({
      profile: { ...DEFAULT },
      setProfile: (p) =>
        set((s) => ({
          profile: { ...s.profile, ...p, updatedAt: new Date().toISOString() },
        })),
      enable: () => set((s) => ({ profile: { ...s.profile, enabled: true } })),
      disable: () => set((s) => ({ profile: { ...s.profile, enabled: false } })),
      reset: () => set({ profile: { ...DEFAULT } }),
    }),
    {
      name: 'prompt-dna-profile',
      storage: createJSONStorage(() => localStorage),
    },
  ),
);