import { Heart } from 'lucide-react';
import { siteConfig } from '@/config/site.config';
import { useLanguage } from './LanguageProvider';

export function Footer() {
  const { t, lang } = useLanguage();

  return (
    <footer className="mt-auto border-t border-border bg-surface/50">
      <div className="mx-auto max-w-7xl px-4 py-8 sm:px-6">
        {/* Dedication banner */}
        <div className="mb-6 rounded-xl border border-primary/20 bg-gradient-to-br from-primary/5 to-accent/5 p-4 text-center">
          <div className="mb-1 flex items-center justify-center gap-2 text-primary">
            <Heart size={16} fill="currentColor" />
            <span className="text-xs font-bold uppercase tracking-wider">
              {lang === 'ar' ? 'صدقة جارية' : 'Sadaqah Jariyah'}
            </span>
            <Heart size={16} fill="currentColor" />
          </div>
          <p className="text-sm font-medium leading-relaxed text-text-primary">
            {lang === 'ar'
              ? 'هذا العمل صدقة جارية على روح الحاج شاكر شحاتة، دعواتكم له بالرحمة والعفو والمغفرة.'
              : 'This work is a ongoing charity dedicated to the soul of Haj Shaker Shehata. Please keep him in your prayers.'}
          </p>
        </div>

        {/* Bottom bar */}
        <div className="flex flex-col items-center justify-between gap-2 border-t border-border pt-4 sm:flex-row">
          <p className="text-sm text-text-muted">
            © {new Date().getFullYear()} {siteConfig.name[lang]} — {t('common.tagline')}
          </p>
          <p className="text-xs text-text-muted">
            v{siteConfig.version} · {siteConfig.author.name}
          </p>
        </div>
      </div>
    </footer>
  );
}