import { Heart } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { useDedicationStore } from '@/lib/store/dedicationStore';
import { useLanguage } from '@/components/layout/LanguageProvider';

export function DedicationModal() {
  const { isOpen, trigger, close } = useDedicationStore();
  const { t } = useLanguage();

  if (!isOpen) return null;

  const successMsg = trigger === 'copy' ? t('dedication.copied') : t('dedication.exported');

  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fade-in"
      onClick={close}
    >
      <div
        className="w-full max-w-md rounded-2xl border border-primary/30 bg-surface-elevated p-6 text-center shadow-2xl animate-slide-up"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mb-4 text-5xl">🤲</div>

        <p className="mb-1 text-sm font-bold text-success">✓ {successMsg}</p>

        <h2 className="mb-4 text-xl font-bold text-gradient">
          {t('dedication.title')}
        </h2>

        <p className="mb-4 text-sm leading-relaxed text-text-primary">
          {t('dedication.description')}
        </p>

        <div className="mb-5 rounded-lg border border-primary/20 bg-primary/5 p-3 text-xs italic leading-relaxed text-text-secondary">
          {t('dedication.prayer')}
        </div>

        <Button fullWidth onClick={close}>
          <Heart size={16} />
          {t('dedication.amen')}
        </Button>
      </div>
    </div>
  );
}