import { Link, NavLink } from 'react-router-dom';
import { Sparkles, History, Settings } from 'lucide-react';
import { siteConfig } from '@/config/site.config';
import { useLanguage } from './LanguageProvider';
import { LanguageSwitcher } from './LanguageSwitcher';
import { ProfileIndicator } from '@/components/profile/ProfileIndicator';
import { cn } from '@/lib/utils/cn';

export function Header() {
  const { t, lang } = useLanguage();

  const navItems = [
    { to: '/', label: t('nav.home'), end: true },
    { to: '/create', label: t('nav.create') },
    { to: '/explore', label: t('nav.explorer') },
    { to: '/custom', label: t('nav.custom') },
    { to: '/history', label: t('nav.history') },
    { to: '/about', label: t('nav.about') },
  ];

  return (
    <header className="sticky top-0 z-40 border-b border-border bg-bg/80 backdrop-blur-xl">
      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between gap-4 px-4 sm:px-6">
        <Link
          to="/"
          className="flex items-center gap-2 transition-transform hover:scale-105 shrink-0"
        >
          <span className="text-2xl">{siteConfig.logo.icon}</span>
          <span className="hidden text-lg font-bold text-gradient sm:inline">
            {siteConfig.name[lang]}
          </span>
        </Link>

        <nav className="hidden items-center gap-1 lg:flex">
          {navItems.map((item) => (
            <NavLink
              key={item.to}
              to={item.to}
              end={item.end}
              className={({ isActive }) =>
                cn(
                  'rounded-lg px-3 py-2 text-sm font-semibold transition-colors',
                  isActive
                    ? 'bg-primary/10 text-primary'
                    : 'text-text-secondary hover:bg-surface hover:text-text-primary',
                )
              }
            >
              {item.label}
            </NavLink>
          ))}
        </nav>

        <div className="flex items-center gap-2">
          <ProfileIndicator />
          <Link
            to="/create"
            className="hidden items-center gap-1.5 rounded-lg bg-primary px-4 py-2 text-sm font-bold text-white transition-all hover:bg-primary-hover glow sm:inline-flex"
          >
            <Sparkles size={16} />
            {t('nav.create')}
          </Link>
          <NavLink
            to="/history"
            className="inline-flex items-center gap-1 rounded-lg border border-border bg-surface p-2 text-text-secondary hover:border-primary hover:text-primary lg:hidden"
            aria-label={t('nav.history')}
          >
            <History size={16} />
          </NavLink>
          <NavLink
            to="/settings"
            className="inline-flex items-center gap-1 rounded-lg border border-border bg-surface p-2 text-text-secondary hover:border-primary hover:text-primary"
            aria-label={t('nav.settings')}
          >
            <Settings size={16} />
          </NavLink>
          <LanguageSwitcher />
        </div>
      </div>
    </header>
  );
}