import React from 'react';
import ReactDOM from 'react-dom/client';
import { HashRouter } from 'react-router-dom';
import { registerSW } from 'virtual:pwa-register';
import App from './app/App';
import './styles/globals.css';
import { loadEnglishExamples } from '@/lib/utils/dataLoader';
import './styles/globals.css';

// ✅ Preload English examples (needed for EN-mode prompt generation)
loadEnglishExamples().catch((e) => console.warn('[preload] english examples failed:', e));
// Register the service worker with auto-update
registerSW({
  immediate: true,
  onNeedRefresh() {
    // Optional: show a toast to reload
    console.log('[PWA] New version available — reload to update.');
  },
  onOfflineReady() {
    console.log('[PWA] App is ready to work offline.');
  },
});

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <HashRouter>
      <App />
    </HashRouter>
  </React.StrictMode>
);
