import React, { createElement } from 'react';
import { User, X } from 'lucide-react';
import { useProfileStore } from '@/lib/store/profileStore';

export function ProfileIndicator() {
  const { profile, disable } = useProfileStore();

  if (!profile.enabled || !profile.name) return null;

  return createElement(
    'div',
    { className: 'flex items-center gap-2 rounded-lg border border-primary/30 bg-primary/10 px-3 py-1.5 text-xs' },
    createElement(User, { size: 14, className: 'text-primary' }),
    createElement(
      'span',
      { className: 'font-bold text-primary' },
      'يعمل ببروفايل: ',
      profile.name
    ),
    createElement(
      'button',
      {
        onClick: disable,
        className: 'rounded p-0.5 text-text-muted hover:bg-surface hover:text-error',
        title: 'إيقاف البروفايل لهذه الجلسة',
        type: 'button',
      },
      createElement(X, { size: 12 })
    )
  );
}